namespace sv_4e32633dc06944cbb46b5d6c1e177cbf.Client.Services;

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> Updates);

public sealed record StatusUpdate(
    string Description,
    string Location,
    DateTimeOffset Timestamp);

namespace sv_4e32633dc06944cbb46b5d6c1e177cbf.Client.Services;

public interface IShipmentService
{
    Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_4e32633dc06944cbb46b5d6c1e177cbf.Client.Services;

namespace sv_4e32633dc06944cbb46b5d6c1e177cbf.Services;

public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment(
            "PKG-001",
            "In Transit",
            "Memphis, TN",
            new DateTimeOffset(2026, 6, 14, 17, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Package picked up", "New York, NY", new DateTimeOffset(2026, 6, 9, 8, 30, 0, TimeSpan.Zero)),
                new("Arrived at sorting facility", "Newark, NJ", new DateTimeOffset(2026, 6, 9, 14, 0, 0, TimeSpan.Zero)),
                new("Departed facility", "Newark, NJ", new DateTimeOffset(2026, 6, 10, 3, 15, 0, TimeSpan.Zero)),
                new("Arrived at regional hub", "Memphis, TN", new DateTimeOffset(2026, 6, 11, 6, 45, 0, TimeSpan.Zero)),
            }),

        ["PKG-002"] = new Shipment(
            "PKG-002",
            "Delivered",
            "San Francisco, CA",
            new DateTimeOffset(2026, 6, 10, 12, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Package picked up", "Seattle, WA", new DateTimeOffset(2026, 6, 7, 9, 0, 0, TimeSpan.Zero)),
                new("In transit", "Portland, OR", new DateTimeOffset(2026, 6, 8, 11, 30, 0, TimeSpan.Zero)),
                new("Out for delivery", "San Francisco, CA", new DateTimeOffset(2026, 6, 10, 7, 0, 0, TimeSpan.Zero)),
                new("Delivered", "San Francisco, CA", new DateTimeOffset(2026, 6, 10, 10, 22, 0, TimeSpan.Zero)),
            }),

        ["PKG-003"] = new Shipment(
            "PKG-003",
            "Processing",
            "Chicago, IL",
            new DateTimeOffset(2026, 6, 18, 15, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Label created", "Chicago, IL", new DateTimeOffset(2026, 6, 11, 0, 5, 0, TimeSpan.Zero)),
            }),
    };

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"Shipment '{trackingNumber}' not found.");
    }
}

using System.Net.Http.Json;

namespace sv_4e32633dc06944cbb46b5d6c1e177cbf.Client.Services;

public sealed class HttpShipmentService(HttpClient http) : IShipmentService
{
    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            throw new KeyNotFoundException($"Shipment '{trackingNumber}' not found.");
        }

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<Shipment>(ct)
            ?? throw new InvalidOperationException("Received null shipment from server.");
    }
}

